#!/usr/bin/env bash
# Production-parity smoke of a built image (ARC.23), run by CI on both architectures before an
# image can be pushed. It turns the runner into a STAGE-like host and deploys the image there with
# the release's own mpmv-deploy, so the containers run under the real Quadlet units (generated by
# the host's Podman quadlet generator, under systemd --user) with the production Caddyfile:
# read-only root, no capabilities, no-new-privileges, user 10001, the mpmv-media volume, env files
# shaped like deploy/server/*.env.example and PostgreSQL over TLS with sslmode=verify-full.
#
#   deploy/ci/parity-smoke.sh <docker image>      e.g. mpmv-app:ci
#
# Every secret is generated here, for this run only. The script changes the runner (sysctl,
# lingering, the runner user's ~/.config): run it on a throwaway CI runner, never on a server.
#
# Caddy and the test site name: the production Caddyfile serves {$MPMV_SITE_ADDRESS} with automatic
# HTTPS. The smoke uses a *.localhost name, for which Caddy issues the certificate from its own
# local CA instead of Let's Encrypt; the root of that CA is generated here and put into the
# mpmv-caddy-data volume before Caddy starts, so curl can verify the certificate. The Caddyfile
# itself is the release's, unchanged.
set -euo pipefail

image="${1:?usage: parity-smoke.sh <docker image>}"
repo="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
work="${RUNNER_TEMP:-/tmp}/mpmv-parity"
site=mpmv-parity.localhost
db_host=mpmv-parity-db
registry=localhost/mpmv-release
good=parity-good
bad=parity-bad
deployer="$HOME/.local/bin/mpmv-deploy"
config="$HOME/.config/mpmv"
units="$HOME/.config/containers/systemd"
started=$SECONDS

group() { echo "::group::$*"; }
endgroup() { echo "::endgroup::"; }
dump() {
  echo "::group::diagnostics"
  podman ps -a || true
  journalctl --user --no-pager -n 200 -u 'mpmv-*' || true
  for c in mpmv-app mpmv-worker mpmv-caddy mpmv-migrate; do podman logs --tail 50 "$c" 2>&1 || true; done
  echo "::endgroup::"
}
fail() {
  echo "::error::parity smoke: $*"
  dump
  exit 1
}
random() { python3 -c 'import secrets; print(secrets.token_urlsafe(32))'; }
unit_value() { sed -n "s/^$2=//p" "$repo/deploy/quadlet/$1" | head -n 1; }

rm -rf "$work"
mkdir -p "$work/pki" "$work/db-tls" "$work/bad"

group "STAGE-like host: systemd --user, rootless Podman, unprivileged 80/443"
sudo sysctl -q -w net.ipv4.ip_unprivileged_port_start=80
# Ubuntu restricts unprivileged user namespaces through AppArmor; rootless Podman needs them.
sudo sysctl -q -w kernel.apparmor_restrict_unprivileged_userns=0 2>/dev/null || true
if ! command -v dbus-daemon >/dev/null || [ ! -e /usr/lib/systemd/user/dbus.socket ]; then
  sudo apt-get -qq update && sudo apt-get -qq install -y dbus-user-session >/dev/null
fi
sudo loginctl enable-linger "$USER"
XDG_RUNTIME_DIR="/run/user/$(id -u)"
export XDG_RUNTIME_DIR
for _ in $(seq 30); do
  if systemctl --user show-environment >/dev/null 2>&1; then break; fi
  sleep 1
done
systemctl --user start dbus.socket 2>/dev/null || true
if [ -S "$XDG_RUNTIME_DIR/bus" ]; then export DBUS_SESSION_BUS_ADDRESS="unix:path=$XDG_RUNTIME_DIR/bus"; fi
podman --version
podman info --format 'cgroup manager {{.Host.CgroupManager}}, cgroups {{.Host.CgroupsVersion}}'
endgroup

group "Release image in Podman's storage"
docker save "$image" -o "$work/image.tar"
loaded="$(podman load -q -i "$work/image.tar" | sed -n 's/^Loaded image[^:]*: *//p' | head -n 1)"
rm -f "$work/image.tar"
podman tag "${loaded:-$image}" "$registry:$good"
endgroup

group "Env files from the examples, throwaway values"
mkdir -p "$config"
chmod 700 "$config"
db_password="$(random)"
field_key="ci:$(python3 -c 'import base64, secrets; print(base64.urlsafe_b64encode(secrets.token_bytes(32)).decode())')"
database_url="$(printf 'postgres://%s:%s@%s:5432/%s?sslmode=verify-full&sslrootcert=/etc/mpmv/pg-root-ca.crt' \
  mpmv "$db_password" "$db_host" mpmv)"
declare -A fill=(
  [DJANGO_SECRET_KEY]="$(random)"
  [MPMV_FIELD_ENCRYPTION_KEYS]="$field_key"
  [DJANGO_ALLOWED_HOSTS]="$site"
  [MPMV_BASE_URL]="https://$site"
  [DATABASE_URL]="$database_url"
  [MPMV_SITE_ADDRESS]="$site"
  [MPMV_NOINDEX]=true
)
for name in mpmv database caddy; do
  while IFS= read -r line; do
    case "$line" in \#* | "") continue ;; esac
    var="${line%%=*}"
    printf '%s=%s\n' "$var" "${fill[$var]:-${line#*=}}"
  done <"$repo/deploy/server/$name.env.example" >"$config/$name.env"
  chmod 600 "$config/$name.env"
done
endgroup

group "PostgreSQL with TLS, server certificate from a throwaway CA"
openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -nodes -days 2 \
  -subj "/CN=MPMV parity database CA" -keyout "$work/pki/db-ca.key" -out "$work/pki/db-ca.crt" \
  -addext basicConstraints=critical,CA:TRUE -addext keyUsage=critical,keyCertSign,cRLSign 2>/dev/null
openssl req -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -nodes -subj "/CN=$db_host" \
  -keyout "$work/db-tls/server.key" -out "$work/pki/server.csr" 2>/dev/null
openssl x509 -req -in "$work/pki/server.csr" -CA "$work/pki/db-ca.crt" -CAkey "$work/pki/db-ca.key" \
  -CAcreateserial -days 2 -out "$work/db-tls/server.crt" \
  -extfile <(printf 'subjectAltName=DNS:%s\nextendedKeyUsage=serverAuth\n' "$db_host") 2>/dev/null
cp "$work/pki/db-ca.crt" "$config/pg-root-ca.crt"
network="$(unit_value mpmv.network NetworkName)"
podman network create --subnet "$(unit_value mpmv.network Subnet)" "$network" >/dev/null
podman run -d --name "$db_host" --network "$network" \
  -e POSTGRES_USER=mpmv -e POSTGRES_DB=mpmv -e POSTGRES_PASSWORD="$db_password" \
  -v "$work/db-tls:/tls:ro" --entrypoint sh docker.io/library/postgres:17 -c '
    install -d -o postgres -m 700 /run/tls &&
    install -o postgres -m 600 /tls/server.key /tls/server.crt /run/tls/ &&
    exec docker-entrypoint.sh postgres -c ssl=on \
      -c ssl_cert_file=/run/tls/server.crt -c ssl_key_file=/run/tls/server.key' >/dev/null
for _ in $(seq 60); do
  if podman exec "$db_host" pg_isready -q -h 127.0.0.1 -U mpmv; then break; fi
  sleep 1
done
podman exec "$db_host" pg_isready -h 127.0.0.1 -U mpmv || fail "PostgreSQL did not start"
endgroup

group "Caddy local CA for the test site name"
openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -nodes -days 30 \
  -subj "/CN=MPMV parity proxy CA" -keyout "$work/pki/proxy-ca.key" -out "$work/pki/proxy-ca.crt" \
  -addext basicConstraints=critical,CA:TRUE -addext keyUsage=critical,keyCertSign,cRLSign 2>/dev/null
caddy_volume="$(sed -n 's/^VolumeName=//p' "$repo/deploy/quadlet/mpmv-caddy-data.volume")"
podman volume create "$caddy_volume" >/dev/null
caddy_data="$(podman volume inspect --format '{{.Mountpoint}}' "$caddy_volume")"
podman unshare sh -c 'd="$1/caddy/pki/authorities/local" && mkdir -p "$d" &&
  cp "$2" "$d/root.crt" && cp "$3" "$d/root.key"' sh \
  "$caddy_data" "$work/pki/proxy-ca.crt" "$work/pki/proxy-ca.key"
endgroup

export MPMV_IMAGE="$registry" MPMV_CHECK_CACERT="$work/pki/proxy-ca.crt"
curl_site() { curl -sS --max-time 10 --resolve "$site:443:127.0.0.1" --cacert "$MPMV_CHECK_CACERT" "$@"; }
status_of() { curl_site -o /dev/null -w '%{http_code}' "https://$site$1"; }
expect_status() { # expect_status <path> <code>
  got="$(status_of "$1")"
  [ "$got" = "$2" ] || fail "GET $1 answered $got, expected $2"
  echo "GET $1 -> $got"
}

group "Install mpmv-deploy from the image, then deploy it (doctor, units, migrate, restart, check)"
mkdir -p "$(dirname "$deployer")"
podman run --rm --network none --entrypoint cat "$registry:$good" /app/deploy/server/mpmv-deploy >"$deployer"
chmod 755 "$deployer"
t0=$SECONDS
"$deployer" deploy "$good" || fail "deploy of the release failed"
echo "deploy took $((SECONDS - t0)) s"
cmp -s "$repo/deploy/caddy/Caddyfile" "$config/Caddyfile" || fail "the installed Caddyfile is not the release's"
for unit in "$repo"/deploy/quadlet/*; do
  cmp -s "$unit" "$units/${unit##*/}" || fail "installed ${unit##*/} differs from the release"
done
endgroup

group "The containers run as the units say"
for c in mpmv-app mpmv-worker; do
  [ "$(podman inspect --format '{{.HostConfig.ReadonlyRootfs}}' "$c")" = true ] || fail "$c root is writable"
  [ "$(podman exec "$c" id -u)" = 10001 ] || fail "$c does not run as 10001"
  podman exec "$c" grep -q '^NoNewPrivs:[[:space:]]*1' /proc/1/status || fail "$c lacks no-new-privileges"
  podman exec "$c" grep -q '^CapEff:[[:space:]]*0*$' /proc/1/status || fail "$c keeps capabilities"
  if podman exec "$c" sh -c 'echo x > /app/parity-probe' 2>/dev/null; then fail "$c can write outside /app/media"; fi
  podman exec "$c" sh -c 'echo x > /app/media/parity-probe && rm /app/media/parity-probe' || fail "$c cannot write media"
done
[ "$(podman exec mpmv-app stat -c %u:%g /app/media)" = 10001:10001 ] || fail "media volume not owned by the image user"
podman exec mpmv-app python manage.py check --deploy --fail-level ERROR
endgroup

group "Demo seed (STAGE settings, MPMV_ALLOW_SEED=1)"
t0=$SECONDS
podman exec -e MPMV_ALLOW_SEED=1 mpmv-app python manage.py seed | tail -n 1
echo "seed took $((SECONDS - t0)) s"
endgroup

group "Pages, media and health through Caddy"
expect_status /healthz 200
expect_status / 200
category="$(podman exec mpmv-app python -c '
from apps.catalog.slugs import CATEGORY_SEGMENTS
from apps.seed.data import CATEGORIES
print("/%s/%s/" % (CATEGORY_SEGMENTS["en"], CATEGORIES[0].slugs["en"]))')"
expect_status "$category" 200
media="$(podman exec mpmv-app find /app/media -type f -name '*.webp' -print -quit)"
[ -n "$media" ] || fail "the seed wrote no .webp file to the media volume"
media_url="/media/${media#/app/media/}"
headers="$(curl_site -D - -o /dev/null "https://$site$media_url" | tr -d '\r')"
echo "$headers"
grep -qiE '^HTTP/[0-9.]+ 200' <<<"$headers" || fail "GET $media_url did not answer 200"
grep -qix 'content-type: image/webp' <<<"$headers" || fail "media not served as image/webp"
grep -qix 'x-content-type-options: nosniff' <<<"$headers" || fail "media without nosniff"
grep -qix "content-security-policy: default-src 'none'; sandbox" <<<"$headers" || fail "media without the sandbox CSP"
grep -qix 'x-robots-tag: noindex, nofollow' <<<"$headers" || fail "MPMV_NOINDEX did not add X-Robots-Tag"
for listing in /media/ "$(dirname "$media_url")/"; do
  got="$(status_of "$listing")"
  [ "$got" != 200 ] || fail "GET $listing lists a media directory"
  echo "GET $listing -> $got (no listing)"
done
"$deployer" check || fail "mpmv-deploy check failed on a good release"
"$deployer" doctor || fail "mpmv-deploy doctor failed on a good release"
endgroup

group "A bad release rolls back, image and units, in under 60 s"
# Same image, a marked unit, and an entry point that migrates fine but never serves.
cp "$repo/deploy/quadlet/mpmv-app.container" "$work/bad/mpmv-app.container"
echo "# parity bad release" >>"$work/bad/mpmv-app.container"
cat >"$work/bad/Containerfile" <<EOF
FROM $registry:$good
COPY mpmv-app.container /app/deploy/quadlet/mpmv-app.container
ENTRYPOINT ["/bin/sh", "-c", "[ \"\$0\" = migrate ]"]
EOF
podman build -q -t "$registry:$bad" -f "$work/bad/Containerfile" "$work/bad" >/dev/null
t0=$SECONDS
if "$deployer" deploy "$bad"; then fail "the bad release went live"; fi
took=$((SECONDS - t0))
echo "bad release detected and rolled back in $took s"
[ "$took" -lt 60 ] || fail "rollback took $took s (limit 60 s)"
"$deployer" status | grep -qx "current: $good" || fail "the good release is not current after the rollback"
if grep -q "parity bad release" "$units/mpmv-app.container"; then fail "the bad release's units stayed installed"; fi
"$deployer" check || fail "the good release does not pass its check after the rollback"
endgroup

echo "parity smoke passed in $((SECONDS - started)) s"
if [ -n "${GITHUB_STEP_SUMMARY:-}" ]; then
  echo "Parity smoke ($(uname -m)): passed in $((SECONDS - started)) s; bad release rolled back in $took s" >>"$GITHUB_STEP_SUMMARY"
fi
